import * as React from "react"
import { ChevronRight } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/lazer/button"
import { Badge } from "@/components/lazer/badge"
import { AspectImage } from "@/components/lazer/aspect-image"

/**
 * Hero Section · Layout=Split · Lazer DS Starter Kit
 * Figma: Landing Page Modules, Hero Section set. Copy and a 3:2 picture side by side
 * from 1024 up; stacked, copy first, below that. Heading/H2, supporting copy capped at 560.
 */
export interface HeroSectionProps extends React.HTMLAttributes<HTMLElement> {
  heading: string
  supporting?: string
  announcement?: { badge: string; message: string; href?: string }
  primaryAction?: { label: string; href?: string; onClick?: () => void }
  secondaryAction?: { label: string; href?: string; onClick?: () => void }
  image?: string
  imageAlt?: string
}

function Action({ label, href, onClick, variant }: { label: string; href?: string; onClick?: () => void; variant: "primary" | "secondary" }) {
  const button = <Button variant={variant} onClick={onClick}>{label}</Button>
  return href ? <a href={href} tabIndex={-1} className="contents">{button}</a> : button
}

export function HeroSection({ heading, supporting, announcement, primaryAction, secondaryAction, image, imageAlt, className, ...props }: HeroSectionProps) {
  return (
    <section
      data-slot="hero-section"
      className={cn("w-full bg-[var(--surface-page)] px-[var(--grid-margin)] py-[var(--space-section-gap)]", className)}
      {...props}
    >
      <div className="mx-auto flex max-w-[var(--layout-content-max)] flex-col gap-[var(--space-content-gap-lg)] lg:flex-row lg:items-center">
        <div className="flex min-w-0 flex-1 flex-col gap-[var(--stack-3xl)]">
          <div className="flex flex-col gap-[var(--stack-2xl)]">
            {announcement ? (
              <a
                href={announcement.href ?? "#"}
                className="lz-body-ui inline-flex w-fit items-center gap-[var(--inline-md)] rounded-[var(--radius-full)] border-[length:var(--stroke-hairline)] border-solid border-[var(--border-default)] bg-[var(--surface-page)] py-[var(--inset-sm)] pl-[var(--inset-sm)] pr-[var(--inset-lg)] text-[var(--text-default)]"
              >
                <Badge tone="accent">{announcement.badge}</Badge>
                {announcement.message}
                <ChevronRight aria-hidden className="size-[var(--component-icon-size-sm)] text-[var(--text-muted)]" />
              </a>
            ) : null}
            <h1 className="lz-h2 text-[var(--text-default)]">{heading}</h1>
            {supporting ? <p className="lz-body max-w-[560px] text-[var(--text-muted)]">{supporting}</p> : null}
          </div>
          {primaryAction || secondaryAction ? (
            <div className="flex flex-wrap gap-x-[var(--inline-md)] gap-y-[var(--stack-md)]">
              {primaryAction ? <Action variant="primary" {...primaryAction} /> : null}
              {secondaryAction ? <Action variant="secondary" {...secondaryAction} /> : null}
            </div>
          ) : null}
        </div>
        <div className="min-w-0 flex-1">
          <AspectImage ratio="3:2" src={image} alt={imageAlt} />
        </div>
      </div>
    </section>
  )
}
